116	// Last returns the last error in the slice. It returns nil if the array is empty.
117	// Shortcut for errors[len(errors)-1].
118	func (a errorMsgs) Last() *Error {
119		if length := len(a); length > 0 {
120			return a[length-1]
121		}
122		return nil
