588	func (engine *Engine) handleHTTPRequest(c *Context) {
589		httpMethod := c.Request.Method
590		rPath := c.Request.URL.Path
591		unescape := false
592		if engine.UseRawPath && len(c.Request.URL.RawPath) > 0 {
593			rPath = c.Request.URL.RawPath
594			unescape = engine.UnescapePathValues
595		}
596	
597		if engine.RemoveExtraSlash {
598			rPath = cleanPath(rPath)
599		}
600	
601		// Find root of the tree for the given HTTP method
602		t := engine.trees
603		for i, tl := 0, len(t); i < tl; i++ {
604			if t[i].method != httpMethod {
605				continue
606			}
607			root := t[i].root
608			// Find route in tree
609			value := root.getValue(rPath, c.params, c.skippedNodes, unescape)
610			if value.params != nil {
611				c.Params = *value.params
612			}
613			if value.handlers != nil {
614				c.handlers = value.handlers
615				c.fullPath = value.fullPath
616				c.Next()
617				c.writermem.WriteHeaderNow()
618				return
619			}
620			if httpMethod != http.MethodConnect && rPath != "/" {
621				if value.tsr && engine.RedirectTrailingSlash {
622					redirectTrailingSlash(c)
623					return
624				}
625				if engine.RedirectFixedPath && redirectFixedPath(c, root, engine.RedirectFixedPath) {
626					return
627				}
628			}
629			break
630		}
631	
632		if engine.HandleMethodNotAllowed {
633			for _, tree := range engine.trees {
634				if tree.method == httpMethod {
635					continue
636				}
637				if value := tree.root.getValue(rPath, nil, c.skippedNodes, unescape); value.handlers != nil {
638					c.handlers = engine.allNoMethod
639					serveError(c, http.StatusMethodNotAllowed, default405Body)
640					return
641				}
642			}
643		}
644		c.handlers = engine.allNoRoute
645		serveError(c, http.StatusNotFound, default404Body)
646	}
