651		c.writermem.status = code
652		c.Next()
653		if c.writermem.Written() {
654			return
655		}
656		if c.writermem.Status() == code {
657			c.writermem.Header()["Content-Type"] = mimePlain
658			_, err := c.Writer.Write(defaultMessage)
659			if err != nil {
