package gin

import (
	"errors"
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestZZProbeUnwrapPointer(t *testing.T) {
	innerErr := TestErr("some error")
	err := fmt.Errorf("wrapped: %w", &Error{
		Err:  innerErr,
		Type: ErrorTypeAny,
	})
	assert.True(t, errors.Is(err, TestErr("some error")))
	var testErr TestErr
	assert.True(t, errors.As(err, &testErr))
}

func TestZZProbeUnwrapValue(t *testing.T) {
	innerErr := TestErr("some error")
	err := fmt.Errorf("wrapped: %w", Error{
		Err:  innerErr,
		Type: ErrorTypeAny,
	})
	assert.True(t, errors.Is(err, TestErr("some error")))
	var testErr TestErr
	assert.True(t, errors.As(err, &testErr))
}

