	c.Status(code)
	c.Writer.WriteHeaderNow()
	c.Abort()
}
```
i.e. `c.Status(500)` → `c.Writer.WriteHeader(500)` (context.go:838–840), then `WriteHeaderNow()` writes the status line/headers to the underlying `http.ResponseWriter` (`w.ResponseWriter.WriteHeader(w.status)`, response_writer.go:69–74), then `c.Abort()` sets `c.index = abortIndex` (context.go:187–189) to stop the chain.

- Status code: **500** (`http.StatusInternalServerError`).
- Body: **no body is written** — only the status code/headers are flushed; no `c.String`/`c.JSON`/`Write` call, so the response body is empty.
- Logging: **defaultHandleRecovery itself does not log anything**; it ignores `err` entirely. Logging is done separately in the deferred recover closure of `CustomRecoveryWithWriter` (lines 71–91) when `out != nil` (logger is `log.New(out, "\n\n\x1b[31m", log.LstdFlags)`), printing `[Recovery] <time> panic recovered: ...` plus the stack from `stack(3)` (and the dumped request headers in debug mode).

### `Recovery`, `CustomRecovery`, `RecoveryWithWriter`, `CustomRecoveryWithWriter` (lines 30–103), in full
```go
// RecoveryFunc defines the function passable to CustomRecovery.
type RecoveryFunc func(c *Context, err any)

// Recovery returns a middleware that recovers from any panics and writes a 500 if there was one.
func Recovery() HandlerFunc {
	return RecoveryWithWriter(DefaultErrorWriter)
}

// CustomRecovery returns a middleware that recovers from any panics and calls the provided handle func to handle it.
func CustomRecovery(handle RecoveryFunc) HandlerFunc {
	return RecoveryWithWriter(DefaultErrorWriter, handle)
}

// RecoveryWithWriter returns a middleware for a given writer that recovers from any panics and writes a 500 if there was one.
func RecoveryWithWriter(out io.Writer, recovery ...RecoveryFunc) HandlerFunc {
	if len(recovery) > 0 {
		return CustomRecoveryWithWriter(out, recovery[0])
	}
	return CustomRecoveryWithWriter(out, defaultHandleRecovery)
}

// CustomRecoveryWithWriter returns a middleware for a given writer that recovers from any panics and calls the provided handle func to handle it.
func CustomRecoveryWithWriter(out io.Writer, handle RecoveryFunc) HandlerFunc {
	var logger *log.Logger
	if out != nil {
		logger = log.New(out, "\n\n\x1b[31m", log.LstdFlags)
	}
	return func(c *Context) {
		defer func() {
			if err := recover(); err != nil {
				// Check for a broken connection, as it is not really a
				// condition that warrants a panic stack trace.
				var brokenPipe bool
				if ne, ok := err.(*net.OpError); ok {
					var se *os.SyscallError
					if errors.As(ne, &se) {
						if strings.Contains(strings.ToLower(se.Error()), "broken pipe") || strings.Contains(strings.ToLower(se.Error()), "connection reset by peer") {
							brokenPipe = true
						}
					}
				}
				if logger != nil {
					stack := stack(3)
					httpRequest, _ := httputil.DumpRequest(c.Request, false)
					headers := strings.Split(string(httpRequest), "\r\n")
					for idx, header := range headers {
						current := strings.Split(header, ":")
						if current[0] == "Authorization" {
							headers[idx] = current[0] + ": *"
						}
					}
					headersToStr := strings.Join(headers, "\r\n")
					if brokenPipe {
						logger.Printf("%s\n%s%s", err, headersToStr, reset)
					} else if IsDebugging() {
						logger.Printf("[Recovery] %s panic recovered:\n%s\n%s\n%s%s",
							timeFormat(time.Now()), headersToStr, err, stack, reset)
					} else {
						logger.Printf("[Recovery] %s panic recovered:\n%s\n%s%s",
							timeFormat(time.Now()), err, stack, reset)
					}
				}
				if brokenPipe {
					// If the connection is dead, we can't write a status to it.
					c.Error(err.(error)) // nolint: errcheck
					c.Abort()
				} else {
					handle(c, err)
				}
			}
		}()
		c.Next()
	}
}
```

### The `Recovery` handler func that calls `defaultHandleRecovery`
There is no separate named handler; the middleware closure returned by `CustomRecoveryWithWriter` is the handler, and it invokes the handler func via `handle(c, err)` (line 97). The default `handle` is `defaultHandleRecovery`, wired in by `RecoveryWithWriter` line 48 (`return CustomRecoveryWithWriter(out, defaultHandleRecovery)`) when no custom `RecoveryFunc` is passed; `Recovery()` (line 34) and `CustomRecovery` (line 39) both go through `RecoveryWithWriter` with `DefaultErrorWriter` (os.Stderr). Note the `brokenPipe` branch (lines 92–95) bypasses `handle` entirely: it does `c.Error(err.(error))` + `c.Abort()` and writes no status.

