	"/a/b/c/d/e", "/a/b/c", "/q", "/q/r", "/q/r/s", "/a/1/2/3/4",
}

// refMatch reports whether pattern matches path and returns the wildcard values in order.
func refMatch(pattern, path string) ([]string, bool) {
	ps := strings.Split(pattern, "/")
	hs := strings.Split(path, "/")
	var vals []string
	for i := 0; i < len(ps); i++ {
		seg := ps[i]
		if strings.HasPrefix(seg, "*") {
			rest := hs[i:]
			if len(rest) == 0 {
				return nil, false
			}
			vals = append(vals, "/"+strings.Join(rest, "/"))
			return vals, true
		}
		if i >= len(hs) {
			return nil, false
		}
		if strings.HasPrefix(seg, ":") {
			if hs[i] == "" {
				return nil, false
			}
			vals = append(vals, hs[i])
			continue
		}
		if seg != hs[i] {
			return nil, false
		}
	}
	if len(hs) != len(ps) {
		return nil, false
	}
	return vals, true
}

func probeWildcards(pattern string) []string {
	var out []string
	for _, seg := range strings.Split(pattern, "/") {
		if strings.HasPrefix(seg, ":") || strings.HasPrefix(seg, "*") {
			out = append(out, seg[1:])
		}
	}
	return out
