				routes = append(routes, p)
			}
		}
		if len(routes) == 0 {
			continue
		}
		r := New()
		panicked := false
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					panicked = true
				}
			}()
			for _, p := range routes {
				pat := p
				r.GET(pat, func(c *Context) {})
			}
		}()
		if panicked {
			continue
		}
		for _, path := range probePaths {
			var got Params
			var fp string
			// re-register with capturing handler
			r2 := New()
			func() {
				defer func() { recover() }()
				for _, p := range routes {
					pat := p
					r2.GET(pat, func(c *Context) {
						got = append(Params{}, c.Params...)
						fp = c.FullPath()
					})
				}
			}()
			w := httptest.NewRecorder()
			req, _ := http.NewRequest("GET", path, nil)
			r2.ServeHTTP(w, req)
			if w.Code != 200 {
				continue
			}
			// handler found: verify params reconstruct the path
			names := probeWildcards(fp)
			if len(got) != len(names) {
				t.Errorf("routes=%v path=%s fullPath=%s: got %d params %v, want %d (names %v)", routes, path, fp, len(got), got, len(names), names)
				fails++
				continue
			}
			for i, n := range names {
				if got[i].Key != n {
					t.Errorf("routes=%v path=%s fullPath=%s: param %d key %q want %q (params %v)", routes, path, fp, i, got[i].Key, n, got)
					fails++
					break
				}
				if got[i].Value == "" {
					t.Errorf("routes=%v path=%s fullPath=%s: param %q EMPTY (params %v)", routes, path, fp, n, got)
					fails++
					break
				}
			}
			// reconstruct
			recon := fp
			for _, p := range got {
				if strings.HasPrefix(p.Key, "") {
					// replace first occurrence of :key or *key
					if idx := strings.Index(recon, ":"+p.Key); idx >= 0 {
						recon = recon[:idx] + p.Value + recon[idx+1+len(p.Key):]
						continue
					}
					if idx := strings.Index(recon, "*"+p.Key); idx >= 0 {
						recon = recon[:idx] + p.Value + recon[idx+1+len(p.Key):]
					}
				}
			}
			if recon != path {
				t.Errorf("routes=%v path=%s fullPath=%s params=%v -> reconstructed %q", routes, path, fp, got, recon)
				fails++
			}
		}
	}
	fmt.Println("done, fails:", fails)
}
